import React, { useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import { toast } from 'react-toastify';
import { ArrowPathIcon, PhotoIcon, XMarkIcon } from '@heroicons/react/24/outline';
import orderService from '../../services/orderService';

const Recycle = () => {
  const navigate = useNavigate();
  const { register, handleSubmit, formState: { errors }, reset } = useForm();
  const [loading, setLoading] = useState(false);
  const [images, setImages] = useState([]);
  const [previewImages, setPreviewImages] = useState([]);

  const handleImageChange = useCallback((e) => {
    if (e.target.files) {
      const filesArray = Array.from(e.target.files);
      if (images.length + filesArray.length > 5) {
        toast.warn('最多只能上传 5 张图片。');
        return;
      }
      setImages(prev => [...prev, ...filesArray]);
      const newPreviews = filesArray.map(file => URL.createObjectURL(file));
      setPreviewImages(prev => [...prev, ...newPreviews]);
    }
  }, [images.length]);

  const removeImage = useCallback((index) => {
    URL.revokeObjectURL(previewImages[index]);
    setImages(prev => prev.filter((_, i) => i !== index));
    setPreviewImages(prev => prev.filter((_, i) => i !== index));
  }, [previewImages]);

  const onSubmit = async (data) => {
    if (images.length === 0) {
      toast.warn('请至少上传一张设备状况的图片。');
      return;
    }

    setLoading(true);
    try {
      const formData = new FormData();
      formData.append('phoneBrand', data.brand);
      formData.append('phoneModel', data.model);
      formData.append('phoneCondition', data.condition);
      formData.append('description', data.description);
      images.forEach(file => formData.append('images', file));

      await orderService.createRecycleOrder(formData);
      toast.success('回收订单已成功提交！');
      reset();
      setImages([]);
      previewImages.forEach(url => URL.revokeObjectURL(url));
      setPreviewImages([]);
      navigate('/profile');
    } catch (error) {
      console.error('提交回收订单失败:', error);
      toast.error(error.response?.data?.message || '提交失败，请稍后重试。');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white min-h-screen">
      <main className="container mx-auto px-4 sm:px-6 lg:px-8">
        <div className="py-16 sm:py-24 text-center">
          <h1 className="text-4xl sm:text-6xl font-bold tracking-tight text-gray-900">
            设备回收
          </h1>
          <p className="mt-4 text-lg sm:text-xl text-gray-600 max-w-2xl mx-auto">
            简单几步，轻松完成估价和回收，让闲置设备变废为宝。
          </p>
        </div>

        <div className="max-w-2xl mx-auto pb-24">
          <form onSubmit={handleSubmit(onSubmit)} className="space-y-8">
            <div>
              <h2 className="text-xl font-semibold text-gray-900">设备信息</h2>
              <div className="mt-6 grid grid-cols-1 gap-y-6 sm:grid-cols-2 sm:gap-x-8">
                <div>
                  <label htmlFor="brand" className="block text-sm font-medium text-gray-700">
                    设备品牌
                  </label>
                  <input
                    type="text"
                    id="brand"
                    {...register('brand', { required: '请输入设备品牌' })}
                    className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                    placeholder="例如：Apple"
                  />
                  {errors.brand && <p className="mt-2 text-sm text-red-600">{errors.brand.message}</p>}
                </div>
                <div>
                  <label htmlFor="model" className="block text-sm font-medium text-gray-700">
                    设备型号
                  </label>
                  <input
                    type="text"
                    id="model"
                    {...register('model', { required: '请输入设备型号' })}
                    className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                    placeholder="例如：iPhone 14 Pro"
                  />
                  {errors.model && <p className="mt-2 text-sm text-red-600">{errors.model.message}</p>}
                </div>
                <div className="sm:col-span-2">
                  <label htmlFor="condition" className="block text-sm font-medium text-gray-700">
                    设备成色
                  </label>
                  <select
                    id="condition"
                    {...register('condition', { required: '请选择设备成色' })}
                    className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                  >
                    <option value="">选择成色</option>
                    <option value="全新">全新未拆封</option>
                    <option value="几乎全新">99新，无使用痕迹</option>
                    <option value="良好">有轻微使用痕迹</option>
                    <option value="一般">有明显划痕或磕碰</option>
                  </select>
                  {errors.condition && <p className="mt-2 text-sm text-red-600">{errors.condition.message}</p>}
                </div>
                <div className="sm:col-span-2">
                  <label htmlFor="description" className="block text-sm font-medium text-gray-700">
                    其他描述
                  </label>
                  <textarea
                    id="description"
                    rows={4}
                    {...register('description')}
                    className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                    placeholder="描述设备的具体状况，如电池健康度、维修历史、功能是否完好等。"
                  />
                </div>
              </div>
            </div>

            <div>
              <h2 className="text-xl font-semibold text-gray-900">设备照片</h2>
              <p className="text-sm text-gray-500 mt-1">请上传真实照片（最多5张），以便我们更准确地估价。</p>
              <div className="mt-4">
                <div className="flex items-center justify-center w-full">
                  <label htmlFor="file-upload" className="flex flex-col items-center justify-center w-full h-32 border-2 border-gray-300 border-dashed rounded-lg cursor-pointer bg-gray-50 hover:bg-gray-100">
                    <div className="flex flex-col items-center justify-center pt-5 pb-6">
                      <PhotoIcon className="w-8 h-8 mb-3 text-gray-400" />
                      <p className="mb-2 text-sm text-gray-500"><span className="font-semibold">点击上传</span> 或拖拽到此</p>
                      <p className="text-xs text-gray-500">支持 PNG, JPG, JPEG 格式</p>
                    </div>
                    <input id="file-upload" type="file" className="hidden" multiple accept="image/*" onChange={handleImageChange} disabled={images.length >= 5} />
                  </label>
                </div>
                {previewImages.length > 0 && (
                  <div className="mt-4 grid grid-cols-3 sm:grid-cols-5 gap-4">
                    {previewImages.map((src, index) => (
                      <div key={src} className="relative group">
                        <img src={src} alt={`预览 ${index + 1}`} className="w-full h-24 object-cover rounded-md" />
                        <button type="button" onClick={() => removeImage(index)} className="absolute top-1 right-1 bg-gray-800 bg-opacity-50 rounded-full p-1 text-white opacity-0 group-hover:opacity-100 transition-opacity">
                          <XMarkIcon className="w-4 h-4" />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>

            <div className="pt-6">
              <button
                type="submit"
                disabled={loading}
                className="w-full flex justify-center py-3 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-gray-400"
              >
                {loading ? (
                  <>
                    <ArrowPathIcon className="animate-spin h-5 w-5 mr-3" />
                    正在提交...
                  </>
                ) : (
                  '确认并提交回收订单'
                )}
              </button>
            </div>
          </form>
        </div>
      </main>
    </div>
  );
};

export default Recycle;
